import {confirmRemoval} from './admin-confirm.js';
import {IDENTITY_PRESETS,validateIdentity,applyIdentity,identityMarkup,identityStyle} from './identity.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function identityEditorMarkup(site){const b=validateIdentity(site.branding);const field=(label,name,value,type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${name==='identityName'?'required maxlength="100"':''}></label>`;return `<form id="identity-form" class="admin-card"><h2>Identitet stranice</h2><p>Uredite naziv, logo i izgled na jednom mjestu. Objava primjenjuje identitet na cijelu stranicu.</p><div class="identity-presets"><button type="button" class="btn outline" data-identity-preset="adria">Adria Maja</button><button type="button" class="btn outline" data-identity-preset="meleh">Meleh</button></div><p class="section-note">Predlošci mijenjaju izgled i naziv istog objekta. Apartmani, fotografije i rezervacije ostaju povezani s njim.</p><div class="form-grid">${field('Naziv stranice','identityName',site.name)}${field('Podnaslov logotipa','subtitle',b.subtitle)}<label>Vrsta logotipa<select name="logoMode"><option value="symbol" ${b.logoMode==='symbol'?'selected':''}>Simbol uz naziv</option><option value="full" ${b.logoMode==='full'?'selected':''}>Cijeli logotip sa svojim natpisom</option></select></label><label>Font naslova<select name="font"><option value="classic" ${b.font==='classic'?'selected':''}>Klasični · Playfair Display</option><option value="modern" ${b.font==='modern'?'selected':''}>Moderni · DM Sans</option></select></label><label>Tema<select name="theme"><option value="classic" ${b.theme==='classic'?'selected':''}>Mediteran</option><option value="adria" ${b.theme==='adria'?'selected':''}>Adria</option></select></label>${field('Naglasak i gumbi','accent',b.accent,'color')}${field('Svijetla pozadina','surface',b.surface,'color')}${field('Boja teksta','ink',b.ink,'color')}<input type="hidden" name="logoUrl" value="${esc(b.logoUrl)}"><input type="hidden" name="faviconUrl" value="${esc(b.faviconUrl)}"><label>Dodaj logotip (PNG, JPG, WebP, do 2 MB)<input type="file" data-identity-upload="logoUrl" accept="image/png,image/jpeg,image/webp"></label><label>Ikona kartice preglednika (do 2 MB)<input type="file" data-identity-upload="faviconUrl" accept="image/png,image/jpeg,image/webp"></label></div><button type="button" class="danger-button" data-identity-clear>Koristi samo tekst naziva</button><div id="identity-preview" class="identity-preview"></div><p id="identity-feedback" role="status"></p><button class="btn">Objavi identitet ↗</button></form>`}
export function captureIdentity(form,site){const values=Object.fromEntries(new FormData(form));return applyIdentity(site,{name:values.identityName,branding:Object.fromEntries(['logoUrl','faviconUrl','logoMode','subtitle','accent','surface','ink','font','theme'].map(k=>[k,values[k]]))})}
export function bindIdentityEditor({site,upload,onSubmit,onError}){const form=document.querySelector('#identity-form');if(!form)return;const feedback=form.querySelector('#identity-feedback');const preview=()=>{try{const next=captureIdentity(form,site);form.querySelector('#identity-preview').innerHTML=`<div style="${identityStyle(next.branding)};background:var(--cream);color:var(--ink);padding:24px">${identityMarkup(next,esc)}<p>Apartmani za vaš odmor.</p><span class="btn" style="background:var(--accent);color:white">Pošalji upit ↗</span></div>`;feedback.textContent='';return true}catch(e){feedback.textContent=e.message;return false}};form.addEventListener('input',preview);form.onsubmit=e=>{e.preventDefault();if(preview())onSubmit()};form.querySelectorAll('[data-identity-preset]').forEach(button=>button.onclick=()=>{const preset=IDENTITY_PRESETS[button.dataset.identityPreset];form.elements.identityName.value=preset.name;for(const [k,v] of Object.entries(preset.branding))form.elements[k].value=v;preview()});form.querySelector('[data-identity-clear]').onclick=()=>{if(!confirmRemoval('Ukloniti logotip i koristiti samo tekst naziva?'))return;form.elements.logoUrl.value='';form.elements.logoMode.value='symbol';preview()};form.querySelectorAll('[data-identity-upload]').forEach(input=>input.onchange=async()=>{const file=input.files[0];if(!file)return;const submit=form.querySelector('button:not([type])');submit.disabled=true;feedback.textContent='Učitavam datoteku…';try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2000000)throw new Error('Dodajte PNG, JPG ili WebP do 2 MB.');form.elements[input.dataset.identityUpload].value=await upload(file);preview();feedback.textContent='Datoteka je učitana. Za primjenu kliknite Objavi identitet.'}catch(e){feedback.textContent=e.message;onError?.(e)}finally{submit.disabled=false;input.value=''}});preview()}
